public String reverseShuffleMerge(String s) {
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) count[s.charAt(i) - 'a']++;
    int[] need = new int[26];
    int target = 0;
    for (int i = 0; i < 26; i++) { need[i] = count[i] / 2; target += need[i]; }
    String rev = new StringBuilder(s).reverse().toString();
    String[] best = {null};
    dfs(rev, 0, new StringBuilder(), new int[26], need, target, best);
    return best[0];
}

private void dfs(String rev, int i, StringBuilder path, int[] used,
                 int[] need, int target, String[] best) {
    if (path.length() == target) {
        String cand = path.toString();
        if (best[0] == null || cand.compareTo(best[0]) < 0) best[0] = cand;
        return;
    }
    if (i == rev.length()) return;
    int c = rev.charAt(i) - 'a';
    if (used[c] < need[c]) {
        used[c]++; path.append(rev.charAt(i));
        dfs(rev, i + 1, path, used, need, target, best);
        path.deleteCharAt(path.length() - 1); used[c]--;
    }
    dfs(rev, i + 1, path, used, need, target, best);
}

public String reverseShuffleMerge(String s) {
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) count[s.charAt(i) - 'a']++;
    int[] need = new int[26];
    for (int i = 0; i < 26; i++) need[i] = count[i] / 2;
    int[] remaining = count.clone();
    int[] used = new int[26];
    StringBuilder stack = new StringBuilder();
    for (int i = s.length() - 1; i >= 0; i--) {
        int c = s.charAt(i) - 'a';
        remaining[c]--;
        if (used[c] >= need[c]) continue;
        while (stack.length() > 0) {
            int top = stack.charAt(stack.length() - 1) - 'a';
            if (top > c && need[top] - used[top] < remaining[top]) {
                stack.deleteCharAt(stack.length() - 1);
                used[top]--;
            } else {
                break;
            }
        }
        stack.append((char) (c + 'a'));
        used[c]++;
    }
    return stack.toString();
}

