def reverseShuffleMerge(self, s: str) -> str:
    from collections import Counter
    count = Counter(s)
    need = {c: v // 2 for c, v in count.items()}
    remaining = dict(count)
    used = {c: 0 for c in count}
    stack: list[str] = []
    for ch in reversed(s):
        remaining[ch] -= 1
        if used[ch] >= need[ch]:
            continue
        while stack and stack[-1] > ch and need[stack[-1]] - used[stack[-1]] < remaining[stack[-1]]:
            used[stack[-1]] -= 1
            stack.pop()
        stack.append(ch)
        used[ch] += 1
    return "".join(stack)

